// Procedural approximations of the Material 3 Expressive shape library
// (circle, square, triangle, pentagon, hexagon, diamond, heart, oval, pill,
// cookie, clover, sunny/burst, flower...). Android's actual shape set ships
// as RoundedPolygon vertex data inside androidx.graphics.shapes, which isn't
// published anywhere as plain SVG path coordinates — so instead every shape
// here is generated by formula and sampled at the *same* point count, in the
// *same* order, so morphing between any two is a trivial per-point linear
// interpolation (the same trick the Android library relies on internally).

// Only the softly-rounded shapes from the M3 Expressive library — no sharp
// polygon corners (triangle/pentagon/hexagon/diamond) and no pointed-spike
// shapes (verySunny/boom), per user request ("chỉ lấy shape có bo tròn mềm").
export type ShapeName =
  | "circle" | "square" | "oval" | "pill"
  | "heart"
  | "cookie4" | "cookie6" | "cookie7" | "cookie9" | "cookie12"
  | "clover4" | "clover8"
  | "sunny" | "softBurst"
  | "flower"
  | "gem";

export type Point = { x: number; y: number };

const SAMPLE_COUNT = 64;

// ── Harmonic shapes: r(theta) = 1 + amp * cos(k*theta) ────────────────────
// Plain cosine gives exactly k lobes. An earlier version used cos(kθ)² · 2-1
// for a "bump" variant meant to avoid inward dips — but that identity is
// just cos(2kθ), silently DOUBLING the lobe count (k=9 rendered as 18
// points, k=12 as 24) which is why every "soft" shape kept coming out
// spiky regardless of which one was picked. Fixed by using one plain-cosine
// formula for everything and keeping amplitudes small for the gentle
// "cookie" family, larger only for the intentionally lobed clover/flower/gem.
const HARMONIC_PARAMS: Partial<Record<ShapeName, { k: number; amp: number }>> = {
  cookie4:    { k: 4,  amp: 0.07 },
  cookie6:    { k: 6,  amp: 0.065 },
  cookie7:    { k: 7,  amp: 0.06 },
  cookie9:    { k: 9,  amp: 0.055 },
  cookie12:   { k: 12, amp: 0.045 },
  clover4:    { k: 4,  amp: 0.26 },
  clover8:    { k: 8,  amp: 0.20 },
  sunny:      { k: 12, amp: 0.10 },
  softBurst:  { k: 10, amp: 0.09 },
  flower:     { k: 5,  amp: 0.18 },
  gem:        { k: 4,  amp: 0.30 },
};

function harmonicRadius(theta: number, k: number, amp: number): number {
  if (k === 0) return 1;
  return 1 + amp * Math.cos(k * theta);
}

// ── Superellipse (squircle): square / oval / pill, via anisotropic scale ─
const SQUIRCLE_PARAMS: Partial<Record<ShapeName, { n: number; a: number; b: number }>> = {
  square: { n: 3,  a: 1,   b: 1 },    // softly rounded, not a sharp-cornered square
  oval:   { n: 2,  a: 1,   b: 0.62 },
  pill:   { n: 5,  a: 1.7, b: 0.78 }, // soft stadium, not flat hard sides
};

function squircleRadius(theta: number, n: number, a: number, b: number): number {
  const c = Math.abs(Math.cos(theta)) / a;
  const s = Math.abs(Math.sin(theta)) / b;
  return 1 / Math.pow(c ** n + s ** n, 1 / n);
}

// ── Heart: classic parametric heart curve, normalized to unit scale ──────
function heartPoint(t: number): Point {
  // t in [0, 2*PI); standard parametric heart, y flipped so the point faces
  // down in SVG's y-down coordinate space.
  const x = 16 * Math.sin(t) ** 3;
  const y = -(13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t));
  return { x: x / 17, y: y / 17 };
}

export function generatePoints(shape: ShapeName, sampleCount: number = SAMPLE_COUNT): Point[] {
  if (shape === "heart") {
    const points: Point[] = [];
    for (let i = 0; i < sampleCount; i++) {
      points.push(heartPoint((i / sampleCount) * Math.PI * 2));
    }
    return points;
  }

  const points: Point[] = [];
  for (let i = 0; i < sampleCount; i++) {
    const theta = (i / sampleCount) * Math.PI * 2;
    let r: number;

    if (shape === "circle") {
      r = 1;
    } else if (SQUIRCLE_PARAMS[shape]) {
      const { n, a, b } = SQUIRCLE_PARAMS[shape]!;
      r = squircleRadius(theta, n, a, b);
    } else {
      const { k, amp } = HARMONIC_PARAMS[shape]!;
      r = harmonicRadius(theta, k, amp);
    }

    points.push({ x: Math.cos(theta) * r, y: Math.sin(theta) * r });
  }
  return points;
}

export function morphPoints(a: Point[], b: Point[], t: number): Point[] {
  const n = Math.min(a.length, b.length);
  const out: Point[] = new Array(n);
  for (let i = 0; i < n; i++) {
    out[i] = {
      x: a[i].x + (b[i].x - a[i].x) * t,
      y: a[i].y + (b[i].y - a[i].y) * t,
    };
  }
  return out;
}

// Catmull-Rom -> cubic Bezier, closed loop, so the outline is a smooth
// curve through the sample points rather than a faceted polygon.
export function toSmoothPath(points: Point[], cx: number, cy: number, radius: number): string {
  const n = points.length;
  const scaled = points.map((p) => ({ x: cx + p.x * radius, y: cy + p.y * radius }));

  let d = `M ${scaled[0].x.toFixed(2)},${scaled[0].y.toFixed(2)} `;
  for (let i = 0; i < n; i++) {
    const p0 = scaled[(i - 1 + n) % n];
    const p1 = scaled[i];
    const p2 = scaled[(i + 1) % n];
    const p3 = scaled[(i + 2) % n];

    const c1x = p1.x + (p2.x - p0.x) / 6;
    const c1y = p1.y + (p2.y - p0.y) / 6;
    const c2x = p2.x - (p3.x - p1.x) / 6;
    const c2y = p2.y - (p3.y - p1.y) / 6;

    d += `C ${c1x.toFixed(2)},${c1y.toFixed(2)} ${c2x.toFixed(2)},${c2y.toFixed(2)} ${p2.x.toFixed(2)},${p2.y.toFixed(2)} `;
  }
  d += "Z";
  return d;
}
